// Plank-join checker for Shipshape.
// Scans implementation directories for @planks and @planks-provisional annotations,
// cross-references them against step-definition patterns and @captain scenarios,
// and exits non-zero on any mismatch.
//
// This checker is the verification support Shipwright authors during fitting out.
// It is run by the plank-join method from RIGGING.md.

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const IMPLEMENTATION_DIRS = ['js'];
const SPECS_DIR = 'features';
const SUPPORT_DIR = path.join(SPECS_DIR, 'support');

// --- Helpers ---

function walkDir(dir) {
  const entries = [];
  if (!fs.existsSync(dir)) return entries;
  for (const name of fs.readdirSync(dir)) {
    const p = path.join(dir, name);
    if (fs.statSync(p).isDirectory()) {
      entries.push(...walkDir(p));
    } else if (/\.(js|mjs|cjs|html)$/.test(name)) {
      entries.push(p);
    }
  }
  return entries;
}

function readFile(p) {
  try {
    return fs.readFileSync(p, 'utf8');
  } catch {
    return '';
  }
}

// --- Step definition patterns ---

function extractStepPatterns(source) {
  // Match cucumber-js step definition patterns:
  //   Given('pattern', ...)
  //   When('pattern', ...)
  //   Then('pattern', ...)
  //   Before(...) / After(...) - ignore
  const patterns = [];
  const regex = /(?:Given|When|Then|And|But)\s*\(\s*(['"`])((?:[^\\]|\\.)*?)\1\s*,/g;
  let match;
  while ((match = regex.exec(source)) !== null) {
    patterns.push(match[2]);
  }
  return patterns;
}

// --- Plank scanning ---

function extractPlanks(source) {
  // Matches @planks("...") and @planks-provisional("...")
  // Both inside docblocks /** ... */ and as bare tokens
  const planks = [];
  const regex = /@planks(?:-provisional)?\s*\(\s*(['"`])((?:[^\\]|\\.)*?)\1\s*\)/g;
  let match;
  while ((match = regex.exec(source)) !== null) {
    planks.push({
      type: match[0].startsWith('@planks-provisional') ? 'provisional' : 'planks',
      value: match[2],
    });
  }
  return planks;
}

// --- @captain scenario references ---

function extractCaptainScenarios(source) {
  const scenarios = [];
  const scenarioRegex = /^\s*@captain\s*$[\s\S]*?^\s*Scenario:\s*(.+)$/gm;
  let match;
  while ((match = scenarioRegex.exec(source)) !== null) {
    scenarios.push(match[1].trim());
  }
  return scenarios;
}

// --- Main ---

let errors = [];

// 1. Collect step-definition patterns from support files
const supportFiles = walkDir(path.join(ROOT, SUPPORT_DIR));
const allPatterns = new Set();
for (const f of supportFiles) {
  const src = readFile(f);
  for (const p of extractStepPatterns(src)) {
    allPatterns.add(p);
  }
}

// 2. Collect @captain scenario names from spec files
const specFiles = walkDir(path.join(ROOT, SPECS_DIR)).filter(
  (f) => !f.startsWith(path.join(ROOT, SUPPORT_DIR))
);
const captainScenarios = new Set();
for (const f of specFiles) {
  const src = readFile(f);
  for (const s of extractCaptainScenarios(src)) {
    captainScenarios.add(s);
  }
}

// 3. Scan implementation directories for planks
const implFiles = [];
for (const dir of IMPLEMENTATION_DIRS) {
  implFiles.push(...walkDir(path.join(ROOT, dir)));
}

for (const f of implFiles) {
  const src = readFile(f);
  const planks = extractPlanks(src);
  for (const plank of planks) {
    if (plank.type === 'planks') {
      // @planks: pattern must match a step definition
      if (!allPatterns.has(plank.value)) {
        errors.push(
          `${path.relative(ROOT, f)}: @planks("${plank.value}") matches no step-definition pattern`
        );
      }
    } else if (plank.type === 'provisional') {
      // @planks-provisional: value is "<spec>.feature:<Scenario Name>"
      const colonIdx = plank.value.indexOf(':');
      if (colonIdx === -1) {
        errors.push(
          `${path.relative(ROOT, f)}: @planks-provisional("${plank.value}") is malformed (expected <spec>.feature:<Scenario Name>)`
        );
        continue;
      }
      const scenarioName = plank.value.slice(colonIdx + 1);
      if (!captainScenarios.has(scenarioName)) {
        errors.push(
          `${path.relative(ROOT, f)}: @planks-provisional("${plank.value}") names no @captain scenario`
        );
      }
    }
  }
}

// 4. Report
if (errors.length > 0) {
  console.error('Plank-join errors:');
  for (const err of errors) {
    console.error('  ' + err);
  }
  process.exit(1);
} else {
  console.log('plank-join: all planks match current patterns and provisional references');
}

