import { readFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { resolve, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = resolve(fileURLToPath(import.meta.url), '..');
const ROOT = resolve(__dirname, '..');
const IMPLEMENTATION_DIRS = ['js'];
const SPECS_DIR = 'features';
const SUPPORT_DIR = join(SPECS_DIR, 'support');

function join(...parts) {
  return resolve(ROOT, ...parts);
}

// --- Helpers ---

function walkDir(dir) {
  const entries = [];
  if (!existsSync(dir)) return entries;
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) {
      entries.push(...walkDir(p));
    } else if (/\.(js|mjs|cjs|html)$/.test(name)) {
      entries.push(p);
    }
  }
  return entries;
}

function readFile(p) {
  try {
    return readFileSync(p, 'utf8');
  } catch {
    return '';
  }
}

// --- Step definition patterns ---

function extractStepPatterns(source) {
  // Match cucumber-js step definition patterns:
  //   Given('pattern', ...)
  //   When('pattern', ...)
  //   Then('pattern', ...)
  const patterns = [];
  const regex = /(?:Given|When|Then|And|But)\s*\(\s*(['"`])((?:[^\\]|\\.)*?)\1\s*,/g;
  let match;
  while ((match = regex.exec(source)) !== null) {
    patterns.push(match[2]);
  }
  return patterns;
}

// --- Plank scanning ---

function extractPlanks(source) {
  // Matches @planks("...") and @planks-provisional("...")
  const planks = [];
  const regex = /@planks(?:-provisional)?\s*\(\s*(['"`])((?:[^\\]|\\.)*?)\1\s*\)/g;
  let match;
  while ((match = regex.exec(source)) !== null) {
    planks.push({
      type: match[0].startsWith('@planks-provisional') ? 'provisional' : 'planks',
      value: match[2],
    });
  }
  return planks;
}

// --- @captain scenario references ---

function extractCaptainScenarios(source) {
  const scenarios = [];
  // Match Scenario lines preceded by @captain
  // @captain can have other tags on the same or adjacent line
  const lines = source.split('\n');
  let hasCaptainTag = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (/^\s*@/.test(line)) {
      if (/\bcaptain\b/.test(line)) {
        hasCaptainTag = true;
      }
      continue;
    }
    const scenarioMatch = line.match(/^\s*Scenario:\s*(.+)$/);
    if (scenarioMatch) {
      if (hasCaptainTag) {
        scenarios.push(scenarioMatch[1].trim());
      }
      hasCaptainTag = false;
    } else if (!/^\s*$/.test(line) && !/^\s*(Feature|Background|Rule|Given|When|Then|And|But|@|\|)/.test(line)) {
      hasCaptainTag = false;
    }
  }
  return scenarios;
}

// --- Main ---

let errors = [];

// 1. Collect step-definition patterns from support files
const supportFiles = walkDir(join(SUPPORT_DIR));
const allPatterns = new Set();
for (const f of supportFiles) {
  const src = readFile(f);
  for (const p of extractStepPatterns(src)) {
    allPatterns.add(p);
  }
}

// 2. Collect @captain scenario names from spec files
const specFiles = walkDir(join(SPECS_DIR)).filter(
  (f) => !f.startsWith(join(SUPPORT_DIR))
);
const captainScenarios = new Set();
for (const f of specFiles) {
  const src = readFile(f);
  for (const s of extractCaptainScenarios(src)) {
    captainScenarios.add(s);
  }
}

// 3. Scan implementation directories for planks
const implFiles = [];
for (const dir of IMPLEMENTATION_DIRS) {
  implFiles.push(...walkDir(join(dir)));
}

for (const f of implFiles) {
  const src = readFile(f);
  const planks = extractPlanks(src);
  for (const plank of planks) {
    if (plank.type === 'planks') {
      if (!allPatterns.has(plank.value)) {
        errors.push(
          `${relative(ROOT, f)}: @planks("${plank.value}") matches no step-definition pattern`
        );
      }
    } else if (plank.type === 'provisional') {
      const colonIdx = plank.value.indexOf(':');
      if (colonIdx === -1) {
        errors.push(
          `${relative(ROOT, f)}: @planks-provisional("${plank.value}") is malformed (expected <spec>.feature:<Scenario Name>)`
        );
        continue;
      }
      const scenarioName = plank.value.slice(colonIdx + 1);
      if (!captainScenarios.has(scenarioName)) {
        errors.push(
          `${relative(ROOT, f)}: @planks-provisional("${plank.value}") names no @captain scenario`
        );
      }
    }
  }
}

// 4. Report
if (errors.length > 0) {
  console.error('Plank-join errors:');
  for (const err of errors) {
    console.error('  ' + err);
  }
  process.exit(1);
} else {
  console.log('plank-join: all planks match current patterns and provisional references');
}

